#include <assert.h>
#include <stdio.h>
#include <math.h>
#include "../native/engine.h"
static void run(tsf*b){assert(b&&tsf_set_max_voices(b,64));tsf_channel_set_presetindex(b,0,0);b->prPedalFade=.8;b->prKeyFade=.25;tsf_channel_midi_control(b,0,64,127);tsf_channel_note_on(b,0,60,1);tsf_channel_note_on(b,0,60,1);unsigned held=b->voicePlayIndex-1;tsf_channel_note_off(b,0,60);float out[128];for(int n=0;n<15;n++)tsf_render_float(b,out,64,0);tsf_channel_midi_control(b,0,64,0);int released=0,pressed=0;for(int i=0;i<b->voiceNum;i++){struct tsf_voice*v=&b->voices[i];if(v->playingPreset<0)continue;if(v->playIndex==held){assert(!v->prKeyReleased&&v->ampenv.segment<TSF_SEGMENT_RELEASE);pressed++;}else{assert(v->prKeyReleased&&v->prFromPedal&&fabsf(v->ampenv.parameters.release-.8)<1e-6);released++;}}assert(pressed==released&&pressed>0);for(int n=0;n<700;n++){tsf_render_float(b,out,64,0);for(int i=0;i<128;i++)assert(isfinite(out[i]));}assert(tsf_active_voice_count(b)==pressed);tsf_channel_note_off(b,0,60);for(int i=0;i<b->voiceNum;i++)if(b->voices[i].playingPreset>=0)assert(fabsf(b->voices[i].ampenv.parameters.release-.25)<1e-6);tsf*clone=tsf_copy(b);assert(clone&&clone->prPedalFade==b->prPedalFade);clone->prPedalFade=0;assert(b->prPedalFade==.8f);tsf_close(clone);tsf_close(b);}
int main(int argc,char**argv){assert(argc==3);run(load_font(argv[1]));tsf*b=load_font(argv[2]);assert(b);tsf_channel_set_presetindex(b,0,0);run(b);puts("PASS: authored SFZ/legacy bank fade after pedal-up, held repeated key stays sounding, completed release drains, separate key-up time, instance/copy isolation and finite PCM.");}
